def seed_rates(apps, schema_editor):
    """Переносимо поточний default_rate кожної послуги у першу запись історії тарифів.

    effective_from = дата створення послуги (тариф діяв з моменту її появи).
    Так current_rate одразу спирається на історію, а не лише на fallback.
    """
    Service = apps.get_model('rentals', 'Service')
    ServiceRate = apps.get_model('rentals', 'ServiceRate')
    for service in Service.objects.all():
        # Послуга вже може мати тарифи (повторний запуск) — не дублюємо
        if service.rates.exists():
            continue
        eff = service.created_at.date() if service.created_at else date(2000, 1, 1)
        ServiceRate.objects.create(
            service=service,
            rate=service.default_rate,
            effective_from=eff,
            note='Початковий тариф (перенесено з default_rate)',
        )


def unseed_rates(apps, schema_editor):
    """Зворотній бік — чистимо тільки авто-перенесені записи."""
    ServiceRate = apps.get_model('rentals', 'ServiceRate')
    ServiceRate.objects.filter(
        note='Початковий тариф (перенесено з default_rate)',
    ).delete()


